    <head>
        <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no">
        <script src="https://www.youtube.com/iframe_api"></script>
            <style>
                body { margin: 0; width:100%%; height:100%%; background-color:#000; }
                #player { width: 100%; height: 100%; }
            </style>
    </head>
    <body>
        <div id="player"></div>
        <script>
            // YouTube player configuration
            var player;
            function onYouTubeIframeAPIReady() {
                player = new YT.Player('player', {
                    height: '360',
                    width: '640',
                    videoId: '<YOUTUBE_ID_PLACEHOLDER>',
                    playerVars: {
                       'playsinline': 1,
                       'rel':0,
                       'fs':0,
                       "modestbranding": 1,
                    },
                    events: {
                        'onReady': onPlayerReady,
                    }
                });
            }

            // Callback function for when the player is ready
            function onPlayerReady(event) {
                window.webkit.messageHandlers.videoPlayerCallbackHandler.postMessage('ready');
            }
        </script>
    </body>
    </html>"

"      <html>
      <head>
          <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no">
          <style>
              body {
                  margin: 0;
                  width: 100%%;
                  height: 100%%;
                  background-color: #000;
              }
              html {
                  width: 100%%;
                  height: 100%%;
                  background-color: #000;
              }
          </style>
      </head>
      <body>
          <iframe id="player"
              src="https://player.vimeo.com/video/<VIMEO_ID_PLACEHOLDER>?autoplay=1&muted=1&controls=0&pip=0&byline=0&interactive_markers=0&background=0"
              frameborder="0" width="100%" height="100%" allow="autoplay; fullscreen" allowfullscreen></iframe>
          <script src="https://player.vimeo.com/api/player.js"></script>
          <script>
              var iframe = document.querySelector('iframe');
              var player = new Vimeo.Player(iframe);

              player.on('play', function () {
                  var messageToPost = { POST_EVENT: "play" };
                  window.webkit.messageHandlers.vimeoPlayerMessageHandler.postMessage(messageToPost);
              });

              player.on('pause', function (data) {
                  var messageToPost = {
                      POST_EVENT: "pause",
                      POST_MESSAGE: data
                  };
                  window.webkit.messageHandlers.vimeoPlayerMessageHandler.postMessage(messageToPost);
              });

              player.on('timeupdate', function (data) {
                  var messageToPost = {
                      POST_EVENT: "timeupdate",
                      POST_MESSAGE: data
                  };
                  window.webkit.messageHandlers.vimeoPlayerMessageHandler.postMessage(messageToPost);
              });

              player.getDuration().then(function (seconds) {
                  var messageToPost = {
                      POST_EVENT: "totalDuration",
                      POST_MESSAGE: seconds
                  };
                  window.webkit.messageHandlers.vimeoPlayerMessageHandler.postMessage(messageToPost);
              });

              player.on('ended', function (data) {
                  var messageToPost = {
                      POST_EVENT: "videoEnded",
                      POST_MESSAGE: data
                  };
                  window.webkit.messageHandlers.vimeoPlayerMessageHandler.postMessage(messageToPost);
              });

              function seekForward() {
                  player.getCurrentTime().then(function (time) {
                      player.setCurrentTime(time + 10);
                  });
              }

              function seekBackward() {
                  player.getCurrentTime().then(function (time) {
                      player.setCurrentTime(Math.max(0, time - 10));
                  });
              }

              function setVolume(volume) {
                  player.setVolume(volume);
              }

              function playVideo() {
                  player.play();
              }

              function pauseVideo() {
                  player.pause();
              }

          </script>
          </body>
      </html>"
